-- No HTTP issuance route. Only the local operator CLI creates these high-entropy, single-use grants.
CREATE TABLE auth_local_recoveries (id TEXT PRIMARY KEY, tokenHash TEXT NOT NULL UNIQUE, userId TEXT NOT NULL REFERENCES users(id), email TEXT NOT NULL, passwordVersion INTEGER NOT NULL, resetMfa INTEGER NOT NULL DEFAULT 0 CHECK(resetMfa IN (0,1)), createdAt TEXT NOT NULL, expiresAt TEXT NOT NULL, consumedAt TEXT, revokedAt TEXT, CHECK(expiresAt>createdAt));
CREATE INDEX auth_local_recoveries_user ON auth_local_recoveries(userId,expiresAt);
CREATE TRIGGER validate_local_recovery BEFORE INSERT ON auth_local_recoveries BEGIN SELECT RAISE(ABORT,'CHECK constraint failed: recovery_account_snapshot') WHERE NOT EXISTS(SELECT 1 FROM users u WHERE u.id=NEW.userId AND lower(u.email)=NEW.email AND u.disabled=0 AND u.passwordVersion=NEW.passwordVersion AND (u.passwordState='active' OR EXISTS(SELECT 1 FROM auth_bootstrap b WHERE b.userId=u.id))); END;
CREATE TRIGGER reissue_local_recovery AFTER INSERT ON auth_local_recoveries BEGIN UPDATE auth_local_recoveries SET revokedAt=NEW.createdAt WHERE userId=NEW.userId AND id<>NEW.id AND consumedAt IS NULL AND revokedAt IS NULL; INSERT INTO audit_log(id,churchId,userId,action,entityId,createdAt) SELECT NEW.id||':'||churchId,churchId,NEW.userId,'security.recovery.issued',NEW.id,NEW.createdAt FROM user_churches WHERE userId=NEW.userId; END;
CREATE TRIGGER revoke_local_recovery_version AFTER UPDATE OF passwordVersion ON users WHEN NEW.passwordVersion<>OLD.passwordVersion BEGIN UPDATE auth_local_recoveries SET revokedAt=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE userId=NEW.id AND consumedAt IS NULL AND revokedAt IS NULL; END;
CREATE TRIGGER revoke_local_recovery_identity AFTER UPDATE OF email,disabled ON users WHEN NEW.email<>OLD.email OR NEW.disabled=1 BEGIN UPDATE auth_local_recoveries SET revokedAt=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE userId=NEW.id AND consumedAt IS NULL AND revokedAt IS NULL; END;
